function ensureUniverse(){if(!game)return;game.clubState??=CLUBS.map((c,i)=>({rating:c[2],finance:randint(40,95),trend:0}));game.decisions??=[];game.rivalries??=[];game.salary??=650;game.player.injury??=0;game.player.stress??=20;game.player.reputation??=15;game.player.potential??=83;game.player.morale??=70;game.worldLog??=[];game.renegotiations??=0;game.activities??=0;}
function power(id){ensureUniverse();return game.clubState[id]?.rating??CLUBS[id][2]}
function weeklyWorld(){ensureUniverse();const c=randint(0,CLUBS.length-1),d=randint(0,CLUBS.length-1);if(c!==d&&rand()<.42){let delta=randint(-2,2);game.clubState[c].rating=clamp(game.clubState[c].rating+delta,48,91);if(Math.abs(delta)>=2){let txt=`${club(c)[0]} ${delta>0?'presenta una promesa surgida de sus inferiores':'atraviesa una mala racha de lesiones'}.`;pushNews('Noticias desde los clubes',txt,'🌍')}}let p=game.player;p.stress=clamp(p.stress+randint(-3,5)+(p.energy<30?5:0),0,100);if(p.injury)pushNews('Seguimiento médico',`El cuerpo médico sigue la recuperación de ${p.name}.`,'🏥');}
function evolveUniverse(){ensureUniverse();const prior=game.awards[0]?.champ;for(let i=0;i<CLUBS.length;i++){let st=game.clubState[i];let prev=st.rating;let delta=randint(-4,4)+(i===prior?1:0);st.rating=clamp(prev+delta,50,92);st.finance=clamp(st.finance+randint(-12,12),10,100);st.trend=delta;}game.player.potential=clamp(game.player.potential+randint(-2,2)+(game.player.form>82?1:0),60,97);pushNews('Mercado de verano','Los equipos cambian sus planteles: algunos se refuerzan y otros pierden figuras.','🔁');let biggest=game.clubState.map((s,i)=>({...s,id:i})).sort((a,b)=>b.trend-a.trend)[0];pushNews('Proyecto en crecimiento',`${club(biggest.id)[0]} mejoró su plantel y aspira a competir más arriba.`,'📈');game.renegotiations=0;game.activities=0;}
function careerAction(which){ensureUniverse();let p=game.player;if(which==='physio'){if(p.money<500)return toast('No alcanza el dinero para el tratamiento');p.money-=500;p.energy=clamp(p.energy+17,0,100);p.injury=Math.max(0,p.injury-1);p.stress=clamp(p.stress-8,0,100);toast('Sesión médica completada');}else if(which==='psych'){if(p.money<250)return toast('Necesitás $250');p.money-=250;p.morale=clamp(p.morale+13,0,100);p.stress=clamp(p.stress-15,0,100);toast('Sesión de bienestar completada');}else if(which==='media'){if(p.energy<10)return toast('Necesitás recuperar energía');p.energy-=8;p.fans=clamp(p.fans+randint(-3,9),0,100);p.stress=clamp(p.stress+4,0,100);toast('Aparición pública registrada');}else if(which==='agent'){if(game.offers.length)return toast('Ya tenés una oferta formal pendiente');let chance=clamp(.16+(p.overall-60)*.009+p.form*.002, .08,.78);if(rand()<chance){const candidates=CLUBS.map((_,i)=>i).filter(i=>i!==p.club);let newClub=pick(candidates);game.offers=[{club:newClub,salary:randint(650,3200),seasons:randint(1,4)}];pushNews('Llamado del representante',`${club(newClub)[0]} abrió conversaciones por tu fichaje.`, '📞');toast('¡Llegó una propuesta!')}else{p.stress=clamp(p.stress+3,0,100);toast('El representante no consiguió ofertas nuevas')} }else if(which==='contract'){if(game.contract>1)return toast('Aún tenés contrato: esperá a la última temporada');if(game.renegotiations>=1)return toast('Ya negociaste esta temporada');game.renegotiations++;let won=rand()<clamp(.2+p.trust/170+p.form/250,.2,.85);if(won){game.contract=randint(2,4);game.salary=Math.round(game.salary*1.35);toast('¡Renovaste tu contrato con una mejora salarial!')}else{p.trust=clamp(p.trust-7,0,100);toast('El club rechazó la renovación por ahora')}}game.activities++;save();render();}
function homeExtras(){ensureUniverse();let p=game.player;return `<div class="section"><h3>Mi situación</h3><small>EN TIEMPO REAL</small></div><div class="grid2"><div class="kpi"><div class="mini-label">ESTADO ANÍMICO</div><strong>${p.morale}%</strong><small>${p.stress}% presión</small></div><div class="kpi"><div class="mini-label">ENFERMERÍA</div><strong>${p.injury?'LESIÓN':'APTO'}</strong><small>${p.injury?`${p.injury} sesiones de recuperación`: 'Disponible para jugar'}</small></div></div><div class="section"><h3>El nivel de tu club</h3></div><div class="card"><div class="setting"><span>Plantel de ${club(p.club)[0]}</span><b>${power(p.club)} GRL</b></div><div class="tiny">Los clubes mejoran o empeoran entre temporadas y por sucesos del universo.</div></div>`}
function worldExtras(){ensureUniverse();let best=game.clubState.map((s,i)=>({...s,id:i})).sort((a,b)=>b.rating-a.rating);return `<div class="section"><h3>Radiografía de la liga</h3><small>PLANTELES DINÁMICOS</small></div><div class="card">${best.slice(0,7).map((s,i)=>`<div class="setting"><span>${i+1}. ${club(s.id)[0]}</span><b>${s.rating} <span style="color:${s.trend>=0?'#d5fc70':'#ff8998'};font-size:10px">${s.trend>0?'+':''}${s.trend}</span></b></div>`).join('')}<p class="tiny">Las variaciones representan cambios simulados de nivel del plantel, no transferencias individuales.</p></div><div class="section"><h3>Mi historia de decisiones</h3></div><div class="card">${game.decisions.slice(-8).reverse().map(d=>`<div class="news-item"><div class="news-icon">🎲</div><div><b>${esc(d.title)}</b><small>${esc(d.choice)} · ${d.season} fecha ${d.round+1}</small></div></div>`).join('')||'<p class="subhead">Todavía no registraste decisiones.</p>'}</div>`}
function playerExtras(){ensureUniverse();let p=game.player;return `<div class="section"><h3>Centro de carrera</h3><small>NUEVO</small></div><div class="card"><div class="setting"><div><span>🏥 Fisioterapia</span><small>Recupera energía y reduce lesiones · $500</small></div><button class="btn compact secondary" onclick="careerAction('physio')">ASISTIR</button></div><div class="setting"><div><span>🧠 Psicología deportiva</span><small>Reduce presión, mejora el ánimo · $250</small></div><button class="btn compact secondary" onclick="careerAction('psych')">ASISTIR</button></div><div class="setting"><div><span>📸 Aparición pública</span><small>Puede mejorar tu relación con hinchas</small></div><button class="btn compact secondary" onclick="careerAction('media')">PARTICIPAR</button></div><div class="setting"><div><span>📞 Llamar al representante</span><small>Preguntar por oportunidades de mercado</small></div><button class="btn compact secondary" onclick="careerAction('agent')">LLAMAR</button></div><div class="setting"><div><span>✍️ Renegociar contrato</span><small>Salario actual $${game.salary}/partido</small></div><button class="btn compact secondary" onclick="careerAction('contract')">NEGOCIAR</button></div></div><div class="section"><h3>Tu techo deportivo</h3></div><div class="card"><div class="setting"><div><span>Potencial estimado</span><small>Influye en el progreso y puede cambiar por temporada</small></div><b>${Math.max(p.overall,p.potential)} GRL</b></div><div class="setting"><span>Estrés acumulado</span><b>${p.stress}/100</b></div><div class="tiny">Tu rendimiento no está predeterminado: lesiones, moral y ritmo de entrenamiento importan.</div></div>`}
window.careerAction=careerAction;


// LEGADO 0.3 — persistent connected football universe. No external libraries or network.
const FIRST=['Mateo','Lautaro','Iker','Santiago','Franco','Enzo','Bruno','Alex','Valentín','Joaquín','Thiago','Lucas','Gabriel','Nicolás','Emiliano','Ezequiel','Ángel','Martín','Facundo','Tomás','Diego','Iván'];
const LAST=['Gómez','Silva','Acosta','Fernández','Romero','Pérez','Díaz','López','Medina','Torres','Morales','Suárez','Martínez','Ortiz','Vega','Herrera','Castro','Rojas','Sosa','Ferreira'];
const COACHES=['M. Salcedo','D. Ferreira','G. Valdés','P. Molina','A. Aguirre','N. Roldán','F. Cabrera','R. Peralta','L. Suárez','S. Méndez'];
function worldPlayer(clubId){let age=randint(17,34);return {id:game.nextPerson++,name:pick(FIRST)+' '+pick(LAST),club:clubId,age,ovr:clamp(Math.round(power(clubId)-8+randint(-13,15)),43,90),pot:randint(67,94),pos:pick(['DEL','MED','DEF','ARQ']),goals:0,assists:0,careerGoals:0,contract:randint(1,4),value:randint(1,30)*100000,injured:0};}
function ensureDeepWorld(){if(!game)return;ensureUniverse();if(!game.people){game.nextPerson=1;game.people=[];for(let clubId=0;clubId<CLUBS.length;clubId++)for(let j=0;j<17;j++)game.people.push(worldPlayer(clubId));}game.coaches??=CLUBS.map((c,i)=>({name:COACHES[i%COACHES.length],style:pick(['Posesión','Presión alta','Contraataque','Bloque bajo']),trust:randint(35,85),years:0}));game.worldTransfers??=[];game.cupHistory??=[];game.cup??={season:game.season,round:0,remaining:[],matches:[],champ:null};game.inbox??=[];game.records??={titles:0,cups:0,topScorer:0};game.player.yellow??=0;game.player.red??=0;game.player.matchRating??=6.5;game.player.fatigue??=0;game.player.legacy??=0;game.lastWorldRound??=-1;}
function worldMessage(title,body){ensureDeepWorld();game.inbox.unshift({title,body,season:game.season,round:game.round});game.inbox=game.inbox.slice(0,50)}
function cupPairings(teams){let arr=[...teams];for(let i=arr.length-1;i>0;i--){let j=randint(0,i);[arr[i],arr[j]]=[arr[j],arr[i]];}const bye=arr.length%2?arr.pop():null;let pairs=[];for(let i=0;i<arr.length;i+=2)pairs.push([arr[i],arr[i+1]]);return {pairs,bye};}
function startWorldSeason(){ensureDeepWorld();for(let person of game.people){person.goals=0;person.assists=0;}game.cup={season:game.season,round:0,remaining:CLUBS.map((_,i)=>i),matches:[],champ:null};worldMessage('Nueva temporada',`Comienza ${game.season}. Habrá copa nacional, nuevos contratos y movimientos de mercado.`);}
function cupRound(){let cup=game.cup;if(cup.champ!==null||cup.remaining.length<2)return;const draw=cupPairings(cup.remaining),winners=draw.bye===null?[]:[draw.bye];let played=[];for(let [a,b] of draw.pairs){let [x,y]=simulateOther(a,b);let winner;if(x===y){winner=rand()<clamp(.5+(power(a)-power(b))*.018,.14,.86)?a:b;}else winner=x>y?a:b;winners.push(winner);played.push({a,b,x,y,winner});}cup.matches.unshift({round:++cup.round,season:game.season,games:played});cup.remaining=winners;if(winners.length===1){cup.champ=winners[0];game.cupHistory.unshift({season:game.season,champ:cup.champ});pushNews('¡Campeón de la copa!',`${club(cup.champ)[0]} conquista la copa nacional.`, '🏆');if(game.player.club===cup.champ){game.records.cups++;game.player.fans=clamp(game.player.fans+9,0,100)}}else{pushNews('Copa nacional',`${winners.length} equipos siguen con vida en la copa.`, '🏆');}}
function advanceWorldRound(){ensureDeepWorld();if(game.lastWorldRound===game.season*100+game.round)return;game.lastWorldRound=game.season*100+game.round;if(typeof legadoAdvance==='function')legadoAdvance();for(let person of game.people){if(rand()<.036){person.goals+=1;person.careerGoals+=1;}if(rand()<.025)person.assists++;if(person.injured>0)person.injured--;else if(rand()<.002)person.injured=randint(1,4);}if(game.round%3===0&&game.cup?.champ===null)cupRound();if(game.round%5===0){let team=randint(0,CLUBS.length-1);const c=game.coaches[team];if(rand()<.28){let prev=c.name;c.name=pick(COACHES);c.style=pick(['Posesión','Presión alta','Contraataque','Bloque bajo']);pushNews('Cambio de técnico',`${club(team)[0]} despide a ${prev} y contrata a ${c.name}.`,'📋');if(team===game.player.club){game.player.trust=clamp(game.player.trust+randint(-23,12),0,100);worldMessage('Nuevo entrenador',`Tu nuevo DT, ${c.name}, prefiere jugar ${c.style.toLowerCase()}. Tenés que ganar su confianza.`);}}}if(game.round%4===0)worldMarket();}
function worldMarket(){ensureDeepWorld();for(let n=0;n<randint(2,6);n++){let who=pick(game.people),before=who.club;let options=CLUBS.map((_,i)=>i).filter(i=>i!==before&&Math.abs(power(i)-who.ovr)<27);if(!options.length)continue;let dest=pick(options);who.club=dest;who.contract=randint(1,4);let fee=Math.round(who.value*(.5+rand())/1000)*1000;const tr={season:game.season,round:game.round,name:who.name,from:before,to:dest,fee};game.worldTransfers.unshift(tr);if(n===0)pushNews('Mercado de pases',`${who.name}: de ${club(before)[0]} a ${club(dest)[0]} por $${fee.toLocaleString('es-AR')}.`,'🔁');}game.worldTransfers=game.worldTransfers.slice(0,100);}
function finishWorldSeason(){ensureDeepWorld();if(game.cup.champ===null){while(game.cup.champ===null)cupRound();}const champ=standing()[0].id;if(champ===game.player.club)game.records.titles++;if(game.player.goals>=12)game.player.legacy+=5;const top=[...game.people].sort((a,b)=>b.goals-a.goals)[0];if(top)pushNews('Goleador del año',`${top.name} (${club(top.club)[0]}) terminó con ${top.goals} goles simulados.`, '🥇');for(let person of game.people){person.age++;person.contract--;let mod=person.age<=23?randint(-1,3):person.age>=32?randint(-4,1):randint(-2,2);person.ovr=clamp(person.ovr+mod,40,95);person.value=Math.round(person.ovr*person.ovr*person.ovr*.3);if(person.age>=37||person.ovr<45){let idx=game.people.indexOf(person);game.people[idx]=worldPlayer(person.club);}if(person.contract<=0)person.contract=randint(1,4);}worldMarket();}
function newInboxView(){ensureDeepWorld();let p=game.player,coach=game.coaches[p.club];let top=[...game.people].sort((a,b)=>b.goals-a.goals).slice(0,8);return `${heading('Tu carrera fuera de la cancha','VIDA Y UNIVERSO','Un mundo que evoluciona aunque no participes.')}<div class="section"><h3>Tu entrenador</h3></div><div class="card"><div class="setting"><span>${esc(coach.name)}</span><b>${esc(coach.style)}</b></div><p class="tiny">Confianza: ${p.trust}/100 · Contrato: ${game.contract} temporadas · Sueldo: $${game.salary} por partido</p></div><div class="section"><h3>Copa nacional</h3></div><div class="card"><div class="setting"><span>Estado</span><b>${game.cup.champ!==null?`Campeón: ${esc(club(game.cup.champ)[0])}`:`${game.cup.remaining.length} clubes en carrera`}</b></div><div class="tiny">La copa avanza automáticamente cada tres fechas. En esta versión se simula y no se juega manualmente.</div>${game.cup.matches.slice(0,2).map(r=>`<p class="tiny">Ronda ${r.round}: ${r.games.slice(0,3).map(m=>`${esc(club(m.a)[0])} ${m.x}-${m.y} ${esc(club(m.b)[0])}`).join(' · ')}</p>`).join('')}</div><div class="section"><h3>Goleadores del universo</h3></div><div class="card">${top.map((a,i)=>`<div class="setting"><span>${i+1}. ${esc(a.name)} <small>${esc(club(a.club)[0])} · ${a.age} años</small></span><b>${a.goals} ⚽</b></div>`).join('')}</div><div class="section"><h3>Mercado internacional de clubes</h3></div><div class="card">${game.worldTransfers.slice(0,9).map(t=>`<div class="news-item"><div class="news-icon">🔁</div><div><b>${esc(t.name)}</b><small>${esc(club(t.from)[0])} → ${esc(club(t.to)[0])} · $${t.fee.toLocaleString('es-AR')}</small></div></div>`).join('')||'<p class="tiny">Todavía no hubo transferencias.</p>'}</div><div class="section"><h3>Mensajes y avisos</h3></div><div class="card">${game.inbox.slice(0,12).map(n=>`<div class="news-item"><div class="news-icon">📨</div><div><b>${esc(n.title)}</b><small>${esc(n.body)}</small></div></div>`).join('')}</div><div class="section"><h3>Tu legado</h3></div><div class="grid2"><div class="kpi"><div class="mini-label">LIGAS</div><strong>${game.records.titles}</strong></div><div class="kpi"><div class="mini-label">COPAS</div><strong>${game.records.cups}</strong></div></div>`;}

window.addEventListener('keydown',e=>{keys[e.key]=true;if(match){if(e.key===' '){e.preventDefault();shoot()}if(e.key.toLowerCase()==='q')pass();if(e.key.toLowerCase()==='e')switchPlayer();if(e.key.startsWith('Arrow'))e.preventDefault()}});window.addEventListener('keyup',e=>keys[e.key]=false);
window.addEventListener('beforeunload',save);window.addEventListener('visibilitychange',()=>{if(document.hidden&&match)cancelAnimationFrame(raf);else if(!document.hidden&&match&&!match.stopped){lastFrame=performance.now();raf=requestAnimationFrame(matchLoop)}});
window.go=go;window.startMatch=startMatch;window.leaveMatch=leaveMatch;window.quickMatch=quickMatch;window.closeResult=closeResult;window.improve=improve;window.doRest=doRest;window.openPending=openPending;window.pendingAction=pendingAction;window.acceptOffer=acceptOffer;window.rejectOffer=rejectOffer;window.confirmReset=confirmReset;window.resetGame=resetGame;window.exportSave=exportSave;window.importSave=importSave;
game=load();if(game)ensureDeepWorld();render();if('serviceWorker' in navigator&&location.protocol.startsWith('http'))navigator.serviceWorker.register('./sw.js').catch(()=>{});
